CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY NOT NULL, user_id TEXT NOT NULL REFERENCES app_user(id) ON DELETE CASCADE, access_token TEXT NOT NULL, access_token_expired_at DATETIME NOT NULL, refresh_token TEXT NOT NULL, refresh_token_expired_at DATETIME NOT NULL, ip_address TEXT NOT NULL, user_agent TEXT NOT NULL, created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME);
